void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 I = fragCoord;
    vec4 O = vec4(0.0);

    float z = 0.0;
    float d = 1e-3;
    float i = 0.0;
    float t = iTime * 3.0;

    for (; i++ < 300.0;
         O += (vec4(0.1) + 0.4 * cos(i * 0.3 + vec4(4.0, 2.0, 6.0, 0.0) + t * 0.5)) / (d + 0.01) / (i + 1.0))
    {
        vec3 p = z * normalize(vec3(I + I, 0.0) - iResolution.xyx);

        p.z -= t * 0.5;
        p.z = mod(p.z, 6.0) - 3.0;

        p = vec3(atan(p.y, p.x) * 2.0, p.z, length(p.xy) - 3.5);

        for (float j = 1.0; j < 7.0; j++) {
            p += sin(p.yzx * j + t * 0.2) / (j * 0.6);
        }

        float tl = abs(p.z) - 0.02;
        float dl = 0.02 * cos(p.x * 8.0) * cos(p.y * 6.0);

        z += d = 0.07 * (tl + dl);
    }

    vec3 cr = tanh(O.rgb * 0.05);
    float sw = smoothstep(0.1, 0.5, z);
    fragColor = vec4(cr * sw, 1.0);
}
